{
  "opening": "This release integrates several key features and fixes from upstream contributions to enhance the library's functionality. The primary focus is on adding parameter support for splitting functions, introducing new zipping utilities, and correcting error handling in existing windowing tools.",
  "requirements": [
    {
      "id": "m01",
      "text": "The functions sliced, split_after, split_at, split_before, and split_when must accept an optional maxsplit parameter that limits the number of splits performed."
    },
    {
      "id": "m07",
      "text": "The function split_at must accept an optional keep_separator parameter that determines whether the separator is included in the resulting chunks."
    },
    {
      "id": "m08",
      "text": "The function zip_equal must raise UnequalIterablesError when the input iterables have different lengths."
    },
    {
      "id": "m10",
      "text": "The function stagger must correctly handle errors or edge cases related to unequal iterable lengths as implied by the branch merge."
    }
  ],
  "closing": "Please ensure all public names are exposed exactly as specified and that the observable behaviors match these requirements."
}
